/**
 * Offer to install the package's coding-agent skills into the user's
 * personal Cursor skills dir under `~/.cursor/skills/agent-sdk/<skill>/`.
 *
 * Cursor walks `~/.cursor/skills` recursively, so the `agent-sdk/` folder is
 * only organizational — identity comes from the leaf folder that holds
 * SKILL.md. Installed copies get `alwaysApply: true` so Cursor injects the
 * skill body as a global rule instead of leaving it as an on-demand catalog
 * entry. Skipped for `--json` / non-TTY hosts.
 *
 * Consumer installs (`npm install` / `npx` of `@grok/agent-sdk`) also copy
 * these skills from a postinstall hook. That path never prompts and never
 * fails the package install. The monorepo source checkout is not a consumer
 * install, so `pnpm install` in everysphere does not overwrite `~/.cursor`.
 */
import { access, chmod, cp, mkdir, readdir, readFile, rm, stat, writeFile } from "node:fs/promises";
import { homedir } from "node:os";
import { join } from "node:path";
import { CLI_COMMAND_NAME, packageRootDir } from "./distribution.js";
import { parseFrontmatter, parseYamlFrontmatter } from "./frontmatter.js";
import { stdoutPalette } from "./terminal-style.js";
import { isRecord } from "./is-record.js";
/** Category folder under ~/.cursor/skills (Cursor discovers nested skills). */
export const CURSOR_SKILLS_NAMESPACE = "agent-sdk";
/**
 * Earlier install folders. Deleted on install so stale skill ids stop
 * being discovered next to the current copies.
 */
const LEGACY_CURSOR_SKILLS_NAMESPACES = ["bdk", "agentsdk", "agentkit"];
/** How long the `init` offer waits for an answer before skipping the install. */
export const SKILL_PROMPT_TIMEOUT_MS = 45_000;
/**
 * Override the resolved `~/.cursor/skills` directory (not the user home).
 * Used by the postinstall hook in tests and publish smoke.
 */
export const CURSOR_JULY_SKILLS_HOME_ENV = "CURSOR_JULY_SKILLS_HOME";
/** Set to `1` to skip the postinstall skill copy. */
export const CURSOR_JULY_SKIP_SKILL_INSTALL_ENV = "CURSOR_JULY_SKIP_SKILL_INSTALL";
export function cursorSkillsHome(home) {
    if (home !== undefined) {
        return join(home.trim() === "" ? homedir() : home, ".cursor", "skills");
    }
    const override = process.env[CURSOR_JULY_SKILLS_HOME_ENV]?.trim();
    if (override !== undefined && override !== "") {
        return override;
    }
    return join(homedir(), ".cursor", "skills");
}
/**
 * True when this package root is an installed copy under `node_modules`
 * (npm, pnpm, yarn, npx, global), not the everysphere source checkout.
 */
export function isConsumerPackageInstall(packageRoot) {
    // Segment check only — split on both separators so a Windows path still
    // matches when this runs (or is tested) on POSIX. Do not rewrite the path.
    return packageRoot.split(/[\\/]/).includes("node_modules");
}
/** `~/.cursor/skills/agent-sdk` — where package skills are installed. */
export function bdkCursorSkillsDir(skillsHome = cursorSkillsHome()) {
    return join(skillsHome, CURSOR_SKILLS_NAMESPACE);
}
function legacyCursorSkillsDirs(skillsHome) {
    return LEGACY_CURSOR_SKILLS_NAMESPACES.map((name) => join(skillsHome, name));
}
/** Absolute install path for one skill: `…/agent-sdk/<leafDir>`. */
export function skillInstallPath(skill, skillsHome = cursorSkillsHome()) {
    return join(bdkCursorSkillsDir(skillsHome), skill.leafDir);
}
/**
 * Skills shipped next to the running package. Uses the frontmatter `name`
 * when present, otherwise `bdk-<dir>`.
 */
export async function listShippedPackageSkills(packageRoot = packageRootDir()) {
    const skillsRoot = join(packageRoot, "skills");
    let entries;
    try {
        entries = await readdir(skillsRoot, { withFileTypes: true });
    }
    catch {
        return [];
    }
    const { name: packageName, version: packageVersion } = await readPackageIdentity(packageRoot);
    const skills = [];
    for (const entry of entries) {
        if (!entry.isDirectory()) {
            continue;
        }
        const sourceDir = join(skillsRoot, entry.name);
        const skillMd = join(sourceDir, "SKILL.md");
        try {
            await access(skillMd);
        }
        catch {
            continue;
        }
        const raw = await readFile(skillMd, "utf8");
        const name = parseFrontmatter(raw).data.name || `${CURSOR_SKILLS_NAMESPACE}-${entry.name}`;
        skills.push({ name, leafDir: entry.name, sourceDir, packageVersion, packageName });
    }
    skills.sort((a, b) => a.leafDir.localeCompare(b.leafDir));
    return skills;
}
const PACKAGE_VERSION_PLACEHOLDER = "__BDK_VERSION__";
const PACKAGE_NAME_PLACEHOLDER = "__BDK_PACKAGE__";
/** Fill skill text with the name and version from package.json. */
export function bindSkillPlaceholders(text, packageName, packageVersion) {
    return text
        .replaceAll(PACKAGE_VERSION_PLACEHOLDER, packageVersion)
        .replaceAll(PACKAGE_NAME_PLACEHOLDER, packageName);
}
async function readPackageIdentity(packageRoot) {
    const raw = await readFile(join(packageRoot, "package.json"), "utf8");
    const manifest = JSON.parse(raw);
    if (!isRecord(manifest) || typeof manifest.name !== "string" || manifest.name.trim() === "") {
        throw new Error("The @grok/agent-sdk package must declare a name.");
    }
    if (typeof manifest.version !== "string" || manifest.version.trim() === "") {
        throw new Error("The @grok/agent-sdk package must declare a version.");
    }
    return { name: manifest.name, version: manifest.version };
}
/**
 * Skills that do not yet have a SKILL.md under ~/.cursor/skills/agent-sdk/.
 * Install still overwrites every shipped skill when the user confirms — this
 * helper is for messaging (fresh install vs update).
 */
export async function findMissingCursorSkills(options) {
    const shipped = await listShippedPackageSkills(options?.packageRoot);
    const home = options?.skillsHome ?? cursorSkillsHome();
    const missing = [];
    for (const skill of shipped) {
        try {
            await access(join(skillInstallPath(skill, home), "SKILL.md"));
        }
        catch {
            missing.push(skill);
        }
    }
    return missing;
}
/**
 * Copy each skill directory into `skillsHome/agent-sdk/<leafDir>/`.
 * Always overwrites so a package upgrade refreshes local Cursor skills.
 * Strips monorepo-only frontmatter, sets `alwaysApply: true` so Cursor
 * loads the body into context, and removes leaf dirs no longer shipped.
 * Also deletes leftover `skillsHome/bdk/`, `skillsHome/agentsdk/`, and
 * `skillsHome/agentkit/`.
 */
export async function installCursorSkills(skills, skillsHome = cursorSkillsHome()) {
    const namespaceDir = bdkCursorSkillsDir(skillsHome);
    await mkdir(namespaceDir, { recursive: true });
    const removed = await orphanLeaves(namespaceDir, skills);
    for (const leaf of removed) {
        await rm(join(namespaceDir, leaf), { recursive: true, force: true });
    }
    const installed = [];
    for (const skill of skills) {
        const target = skillInstallPath(skill, skillsHome);
        await cp(skill.sourceDir, target, { recursive: true, force: true });
        // cp() preserves source modes, and installs can come from read-only
        // stores (Bazel runfiles, pnpm's content-addressed store, nix). Make the
        // copies writable so the SKILL.md rewrite below and the overwrite on the
        // next upgrade both work.
        await makeTreeWritable(target);
        const skillMdPath = join(target, "SKILL.md");
        const raw = await readFile(skillMdPath, "utf8");
        const adjusted = prepareSkillMarkdownForCursorInstall(raw, skill.packageVersion, skill.packageName);
        if (adjusted !== raw) {
            await writeFile(skillMdPath, adjusted, "utf8");
        }
        installed.push(skill.leafDir);
    }
    const removedLegacyDirs = await removeLegacyCursorSkillsNamespaces(skillsHome);
    return { installed, removed, removedLegacyDirs };
}
async function makeTreeWritable(root) {
    await addOwnerWrite(root);
    const entries = await readdir(root, { withFileTypes: true });
    for (const entry of entries) {
        const child = join(root, entry.name);
        if (entry.isDirectory()) {
            await makeTreeWritable(child);
        }
        else {
            await addOwnerWrite(child);
        }
    }
}
/** Add owner-write, preserving every other mode bit (e.g. exec on scripts). */
async function addOwnerWrite(path) {
    const mode = (await stat(path)).mode & 0o7777;
    if ((mode & 0o200) === 0) {
        await chmod(path, mode | 0o200);
    }
}
/** Installed leaf dirs the package no longer ships. Installing deletes these. */
async function orphanLeaves(namespaceDir, skills) {
    const shipped = new Set(skills.map((skill) => skill.leafDir));
    let entries;
    try {
        entries = await readdir(namespaceDir, { withFileTypes: true });
    }
    catch {
        return [];
    }
    return entries
        .filter((entry) => entry.isDirectory() && !shipped.has(entry.name))
        .map((entry) => entry.name);
}
/** Drop leftover earlier install folders so stale skill ids are not discovered. */
async function removeLegacyCursorSkillsNamespaces(skillsHome) {
    const present = await existingLegacyCursorSkillsDirs(skillsHome);
    for (const dir of present) {
        await rm(dir, { recursive: true, force: true });
    }
    return present;
}
async function existingLegacyCursorSkillsDirs(skillsHome) {
    const present = [];
    for (const dir of legacyCursorSkillsDirs(skillsHome)) {
        try {
            await stat(dir);
            present.push(dir);
        }
        catch {
            continue;
        }
    }
    return present;
}
/**
 * Drop monorepo `paths` globs, set `alwaysApply: true` so Cursor injects the
 * body as a global rule, stamp `metadata.version` and bind package commands
 * to the installing version, and fix package doc links for ~/.cursor installs.
 */
export function prepareSkillMarkdownForCursorInstall(content, packageVersion, packageName) {
    const match = /^---\r?\n([\s\S]*?)\r?\n---/.exec(content);
    if (match === null) {
        return content;
    }
    const frontmatter = withVersion(withAlwaysApply(stripPathsFromFrontmatter(match[1] ?? "")), packageVersion);
    const body = content.slice(match[0].length);
    const adjustedBody = body.replace(/\[`docs\/([^`]+)`\]\(\.\.\/\.\.\/docs\/[^)]+\)/g, "docs/$1 in the @grok/agent-sdk package");
    if (adjustedBody.includes(PACKAGE_VERSION_PLACEHOLDER) &&
        (packageVersion === undefined || packageVersion.trim() === "")) {
        throw new Error("Cannot install a BDK skill without a package version.");
    }
    if (adjustedBody.includes(PACKAGE_NAME_PLACEHOLDER) &&
        (packageName === undefined || packageName.trim() === "")) {
        throw new Error("Cannot install a BDK skill without a package name.");
    }
    const boundBody = bindSkillPlaceholders(adjustedBody, packageName ?? PACKAGE_NAME_PLACEHOLDER, packageVersion ?? PACKAGE_VERSION_PLACEHOLDER);
    return `---\n${frontmatter.trimEnd()}\n---${boundBody}`;
}
function stripPathsFromFrontmatter(frontmatter) {
    const lines = frontmatter.split(/\r?\n/);
    const out = [];
    for (let i = 0; i < lines.length; i++) {
        const line = lines[i] ?? "";
        if (line.trimStart().startsWith("paths:")) {
            i++;
            while (i < lines.length && /^[ \t]*-/.test(lines[i] ?? "")) {
                i++;
            }
            i--;
            continue;
        }
        out.push(line);
    }
    return out.join("\n");
}
/**
 * Cursor loads `alwaysApply: true` skills as global rules, not catalog rows.
 * A situational skill opts out with an explicit `alwaysApply: false`.
 */
function withAlwaysApply(frontmatter) {
    if (/^\s*alwaysApply\s*:\s*false\s*$/m.test(frontmatter)) {
        return frontmatter;
    }
    const without = frontmatter
        .split(/\r?\n/)
        .filter((line) => !/^\s*alwaysApply\s*:/.test(line))
        .join("\n")
        .replace(/\n+$/, "");
    if (without === "") {
        return "alwaysApply: true";
    }
    return `${without}\nalwaysApply: true`;
}
/**
 * Agent Skills `metadata.version`: the package release the copy came from,
 * so `skills list` can tell a stale install from a current one. Source
 * skills declare no `metadata` (skills-docs.test.ts checks); the installer
 * owns the key.
 */
function withVersion(frontmatter, packageVersion) {
    if (packageVersion === undefined || packageVersion.trim() === "") {
        return frontmatter;
    }
    return `${frontmatter.replace(/\n+$/, "")}\nmetadata:\n  version: ${JSON.stringify(packageVersion)}`;
}
/** `metadata.version` of an installed SKILL.md, or undefined when absent. */
export function installedSkillVersion(content) {
    const metadata = parseYamlFrontmatter(content).data.metadata;
    if (!isRecord(metadata)) {
        return undefined;
    }
    const version = metadata.version;
    return typeof version === "string" ? version : undefined;
}
/** What an install would do, for the offer and for `install-skills`. */
export async function planSkillInstall(options) {
    const skillsHome = options?.skillsHome ?? cursorSkillsHome();
    const directory = bdkCursorSkillsDir(skillsHome);
    const shipped = await listShippedPackageSkills(options?.packageRoot);
    const present = await Promise.all(shipped.map(async (skill) => {
        try {
            await access(join(skillInstallPath(skill, skillsHome), "SKILL.md"));
            return true;
        }
        catch {
            return false;
        }
    }));
    return {
        shipped,
        skillsHome,
        directory,
        leaves: shipped.map((skill) => skill.leafDir),
        firstInstall: present.every((isPresent) => !isPresent),
        orphans: await orphanLeaves(directory, shipped),
        legacyDirs: await existingLegacyCursorSkillsDirs(skillsHome),
    };
}
/** `Installed 9 BDK skills`, what it dropped, and where it went. */
export function formatSkillInstall(plan, result) {
    const noun = result.installed.length === 1 ? "skill" : "skills";
    const verb = plan.firstInstall ? "Installed" : "Updated";
    const lines = [`${verb} ${result.installed.length} BDK ${noun}`];
    if (result.removed.length > 0) {
        lines.push(`  removed:  ${result.removed.join(", ")}`);
    }
    for (const dir of result.removedLegacyDirs) {
        lines.push(`  removed:  ${dir}`);
    }
    lines.push(`  location: ${plan.directory}`);
    return `${lines.join("\n")}\n`;
}
/**
 * Copy shipped coding-agent skills into ~/.cursor/skills/agent-sdk during a
 * consumer `npm install` / `npx`. Never throws: a failed copy must not fail
 * the package install. No-op in the monorepo source tree and when
 * `CURSOR_JULY_SKIP_SKILL_INSTALL=1`.
 */
export async function syncCursorSkillsOnPackageInstall(options = {}) {
    try {
        const env = options.env ?? process.env;
        if (env[CURSOR_JULY_SKIP_SKILL_INSTALL_ENV] === "1") {
            return { status: "skipped", reason: "opt-out" };
        }
        const packageRoot = options.packageRoot ?? packageRootDir();
        const consumer = options.consumer ?? isConsumerPackageInstall(packageRoot);
        if (!consumer) {
            return { status: "skipped", reason: "not-consumer" };
        }
        const plan = await planSkillInstall({
            packageRoot,
            skillsHome: options.skillsHome,
        });
        if (plan.shipped.length === 0) {
            return { status: "skipped", reason: "no-skills" };
        }
        const result = await installCursorSkills(plan.shipped, plan.skillsHome);
        const out = options.out ?? ((text) => process.stderr.write(text));
        out(formatSkillInstall(plan, result));
        return {
            status: "installed",
            installed: result.installed,
            removed: result.removed,
        };
    }
    catch {
        return { status: "skipped", reason: "error" };
    }
}
/**
 * On a TTY, offer to install/update every shipped package skill into
 * ~/.cursor/skills/agent-sdk (always overwriting). No-op when non-interactive
 * or the package ships no skills. An unanswered prompt skips the install
 * rather than blocking the caller — see `SKILL_PROMPT_TIMEOUT_MS`.
 */
export async function offerInstallCursorSkills(options = {}) {
    const out = options.out ?? ((text) => process.stdout.write(text));
    const interactive = options.interactive ?? (process.stdin.isTTY && process.stdout.isTTY);
    if (!interactive) {
        return { installed: [], skipped: true };
    }
    const plan = await planSkillInstall({
        packageRoot: options.packageRoot,
        skillsHome: options.skillsHome,
    });
    if (plan.shipped.length === 0) {
        return { installed: [], skipped: true };
    }
    const noun = plan.shipped.length === 1 ? "skill" : "skills";
    const verb = plan.firstInstall ? "Install" : "Update";
    const c = stdoutPalette();
    out(`${verb} ${plan.shipped.length} BDK ${noun} in ${plan.directory}?\n`);
    out(c.dim(`  ${plan.leaves.join(", ")}\n`));
    if (!plan.firstInstall) {
        out(c.dim("  (overwrites existing copies with the package version)\n"));
    }
    if (plan.orphans.length > 0) {
        out(c.dim(`  (deletes ${plan.orphans.join(", ")})\n`));
    }
    for (const dir of plan.legacyDirs) {
        out(c.dim(`  (deletes leftover ${dir})\n`));
    }
    const confirm = options.confirm ??
        ((q) => promptYesNo(q, {
            defaultYes: true,
            out,
            timeoutMs: SKILL_PROMPT_TIMEOUT_MS,
        }));
    const accepted = await confirm(`${verb} now?`);
    if (accepted !== true) {
        // `undefined` is the prompt timing out or stdin closing; both mean nobody
        // said yes, so do not claim a duration neither case is guaranteed to have.
        const why = accepted === undefined ? "No answer — skipped the skill install." : "Skipped skill install.";
        out(c.dim(`${why}\nInstall later: ${CLI_COMMAND_NAME} skills install (${plan.directory})\n\n`));
        return { installed: [], skipped: true };
    }
    const result = await installCursorSkills(plan.shipped, plan.skillsHome);
    out(`${formatSkillInstall(plan, result)}\n`);
    return { installed: result.installed, skipped: false };
}
/**
 * Ask a yes/no question. Resolves `undefined` when the answer never comes —
 * the prompt timed out, or stdin closed on an empty line.
 */
export async function promptYesNo(question, options) {
    const hint = options.defaultYes ? "Y/n" : "y/N";
    const input = options.input ?? process.stdin;
    options.out(`${question} [${hint}] `);
    input.resume();
    const line = await readOneLine(input, options.timeoutMs);
    input.pause();
    if (line === undefined) {
        options.out("\n");
        return undefined;
    }
    if (line.trim() === "") {
        return options.defaultYes;
    }
    const answer = line.trim().toLowerCase();
    if (answer === "y" || answer === "yes") {
        return true;
    }
    if (answer === "n" || answer === "no") {
        return false;
    }
    return options.defaultYes;
}
/** The line, or `undefined` when the stream ends or the clock runs out first. */
function readOneLine(stream, timeoutMs) {
    return new Promise((resolve) => {
        let buffer = "";
        let timer;
        const onData = (chunk) => {
            buffer += typeof chunk === "string" ? chunk : chunk.toString("utf8");
            const newline = buffer.indexOf("\n");
            if (newline === -1) {
                return;
            }
            cleanup();
            resolve(buffer.slice(0, newline).replace(/\r$/, ""));
        };
        // EOF and the timeout both land here. A tty holds a half-typed line until
        // Enter, so a non-empty buffer only ever happens on piped input.
        const giveUp = () => {
            cleanup();
            resolve(buffer === "" ? undefined : buffer.replace(/\r$/, ""));
        };
        const cleanup = () => {
            if (timer !== undefined) {
                clearTimeout(timer);
            }
            stream.off("data", onData);
            stream.off("end", giveUp);
        };
        stream.on("data", onData);
        stream.on("end", giveUp);
        if (timeoutMs !== undefined && timeoutMs > 0) {
            timer = setTimeout(giveUp, timeoutMs);
            // Never keep the process alive purely to wait for an answer.
            timer.unref();
        }
    });
}
